from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    def is_sep_row(r): v=g[r][0]; return v!=bg and all(c==v for c in g[r])
    def is_sep_col(c): v=g[0][c]; return v!=bg and all(g[r][c]==v for r in range(h))
    sr=[i for i in range(h) if is_sep_row(i)]
    sc=[j for j in range(w) if is_sep_col(j)]
    g2=[row[:] for row in g]
    if len(sr)>=len(sc) and sr:
        block=[row[:] for row in g[:sr[0]]]
        starts=[0]+[s+1 for s in sr]; ends=sr+[h]
        for st,en in zip(starts,ends):
            if st==0: continue
            for i in range(en-st): g2[st+i]=block[i][:]
    elif sc:
        block=[[g[r][c] for c in range(sc[0])] for r in range(h)]
        starts=[0]+[s+1 for s in sc]; ends=sc+[w]
        for st,en in zip(starts,ends):
            if st==0: continue
            for c in range(st,en):
                for r in range(h): g2[r][c]=block[r][c-st]
    return g2

